const TC = { left: [0, 0, 54], right: [0, 0, 54], gas: [0, 0, 60], brake: [0, 0, 46], nitro: [0, 0, 40], hb: [0, 0, 38], pause: [0, 0, 26], cam: [0, 0, 26], flip: [0, 0, 26] };
