const tc = { left: false, right: false, gas: false, brake: false, drift: false };
const tv1 = new THREE.Vector3(), tv2 = new THREE.Vector3(), tv3 = new THREE.Vector3(), tv4 = new THREE.Vector3();
const tq1 = new THREE.Quaternion(), tq2 = new THREE.Quaternion(), tm1 = new THREE.Matrix4();
let shakeT = 0, shakeAmp = 0;

function engineAccel(v) { return v < 20 ? 30 : Math.max(3, 30 - 22 * (v - 20) / 26); }
function updateGroundPose() {
evalSurf(car.pc, car.s, car.u, SF);
car.pos.copy(SF.q).addScaledVector(SF.n, RIDE);
const ca = Math.cos(car.a), sa = Math.sin(car.a);
car.fwd.copy(SF.t).multiplyScalar(ca).addScaledVector(SF.l, sa);
car.up.copy(SF.n);
tv1.crossVectors(car.up, car.fwd);
tm1.makeBasis(tv1, car.up, car.fwd);
car.q.setFromRotationMatrix(tm1);
car.vel.copy(SF.t).multiplyScalar(car.vt).addScaledVector(SF.l, car.vl);
car.speed = Math.sqrt(car.vt * car.vt + car.vl * car.vl);
}
function launch() {
car.vel.copy(SF.t).multiplyScalar(car.vt).addScaledVector(SF.l, car.vl);
car.mode = 'air'; car.pc = null; car.airT = 0; car.offT = 0;
if (car.speed > 22) snd(300, 0.12, { type: 'triangle', slide: 520, vol: 0.08 });
}
function addShake(a) { if (reducedMotion) return; shakeT = 0.28; shakeAmp = Math.max(shakeAmp, a); }

function transit(dir) {
const pc = car.pc, nb = dir > 0 ? pc.next : pc.prev, rev = dir > 0 ? pc.nextRev : pc.prevRev;
const lim = nb ? (nb.def.pipe ? PIPE_MAX : HW + 0.3) : 0;
if (!nb || Math.abs(car.u) > lim) {
car.s = dir > 0 ? pc.len : 0;
if (race && race.phase === 'done') { car.vt = 0; car.vl = 0; updateGroundPose(); return false; } // park at the track end
updateGroundPose();
launch();
return false;
}
const over = dir > 0 ? car.s - pc.len : -car.s;
if (!rev) car.s = dir > 0 ? over : nb.len - over;
else {
car.s = dir > 0 ? nb.len - over : over;
car.u = -car.u; car.a = wrapA(car.a + Math.PI); car.vt = -car.vt; car.vl = -car.vl;
}
car.s = clamp(car.s, 0, nb.len);
car.pc = nb;
return true;
}

function groundStep(dt) {
const pc = car.pc;
evalSurf(pc, car.s, car.u, SF);
let ca = Math.cos(car.a), sa = Math.sin(car.a);
let vf = car.vt * ca + car.vl * sa, vs = -car.vt * sa + car.vl * ca;
if (pc.def.boost) {
if (car.boostPc !== pc) {
if (car.boostT < 0.2) { snd(320, 0.35, { type: 'sawtooth', slide: 900, vol: 0.07 }); noise(0.3, { filter: 2400, vol: 0.12 }); }
car.boostTo = Math.max(car.boostT > 0 ? car.boostTo : 0, vf + BOOST_ADD);
car.boostPc = pc;
}
car.boostT = BOOST_TIME;
} else car.boostPc = null;
if (car.boostT > 0 && vf < car.boostTo) vf = Math.min(car.boostTo, vf + BOOST_ACC * dt);
if (inp.gas && !inp.brake) {
if (vf < 0) vf += 60 * dt;
else vf += engineAccel(vf) * dt;
} else if (inp.brake && !inp.gas) {
const done = !!race && race.phase === 'done';
if (vf > 0.5) vf = Math.max(0, vf - (done ? 110 : 60) * dt);
else if (done) vf = 0;                       // after the finish: stop, never reverse
else if (vf > -14) vf = Math.max(-14, vf - 18 * dt);
} else {
const dec = (2.5 + 0.05 * Math.abs(vf)) * dt;
vf = Math.abs(vf) <= dec ? 0 : vf - (vf > 0 ? dec : -dec);
}
const drifting = inp.hand && Math.abs(vf) > 12;
if (inp.hand && !drifting) { const d = 30 * dt; vf = Math.abs(vf) <= d ? 0 : vf - (vf > 0 ? d : -d); }
if (drifting) vf -= (vf > 0 ? 3 : -3) * dt;
car.drifting = drifting;
const sp = Math.abs(vf);
const rate = (2.5 - 1.05 * Math.min(1, sp / VMAX)) * Math.min(1, sp / 4) * (drifting ? 1.5 : 1);
car.a = wrapA(car.a + car.steer * rate * (vf < 0 ? -1 : 1) * dt);
vs *= Math.exp(-(drifting ? 1.6 : 9) * dt);
ca = Math.cos(car.a); sa = Math.sin(car.a);
car.vt = vf * ca - vs * sa; car.vl = vf * sa + vs * ca;
car.vt += -GRAV * SF.t.y * 0.55 * dt;
if (pc.def.pipe) car.vl += -GRAV * SF.l.y * dt;
const push = car.vt * car.vt * SF.kn + car.vl * car.vl * SF.kc + GRAV * SF.n.y + (SF.kn < 0 ? 0.04 * car.vt * car.vt : 0);
if (push < -2) { car.speed = Math.sqrt(car.vt * car.vt + car.vl * car.vl); launch(); return; }
const metric = Math.max(0.25, 1 - SF.kg * car.u);
const dsc = car.vt * dt / metric;
car.s += dsc;
car.u += car.vl * dt;
const dpsi = pc.def.loop ? 0 : SF.kg * dsc * (1 - 0.8 * SF.bank);
if (dpsi !== 0) {
car.a = wrapA(car.a - dpsi);
const c = Math.cos(dpsi), s = Math.sin(dpsi), vt = car.vt * c + car.vl * s, vl = -car.vt * s + car.vl * c;
car.vt = vt; car.vl = vl;
}
const lim = pc.def.pipe ? LIM_PIPE : LIM_FLAT;
if (car.u > lim || car.u < -lim) {
const sg = car.u > 0 ? 1 : -1, into = car.vl * sg;
car.u = sg * lim;
if (into > 0) {
car.vl = -car.vl * 0.12;
if (car.a * sg > 0 && Math.abs(car.a) < 1.4) car.a *= 1 - Math.min(1, 8 * dt);
if (into > 3 && car.wallT <= 0) { // one speed penalty per impact, then only scraping friction
car.wallT = 0.15;
car.vt *= 1 - Math.min(0.35, into / 110);
noise(0.1, { filter: 900, vol: Math.min(0.3, 0.06 + into * 0.006) });
if (into > 22) addShake(0.25);
const wx = car.pos.x + SF.l.x * sg * 1.1, wy = car.pos.y + SF.l.y * sg * 1.1, wz = car.pos.z + SF.l.z * sg * 1.1;
for (let k = 0; k < 6; k++) emit(wx, wy, wz, (Math.random() - 0.5) * 8 - car.vel.x * 0.1, Math.random() * 6, (Math.random() - 0.5) * 8 - car.vel.z * 0.1, 0.35, 1, 0.75, 0.3, 18);
}
}
const d = (4 + Math.max(0, into) * 1.5) * dt;
car.vt = Math.abs(car.vt) <= d ? 0 : car.vt - (car.vt > 0 ? d : -d);
}
if (car.s > pc.len) { if (!transit(1)) return; }
else if (car.s < 0) { if (!transit(-1)) return; }
updateGroundPose();
if (drifting && Math.random() < 0.6) {
const side = Math.random() < 0.5 ? -0.9 : 0.9;
tv1.crossVectors(car.up, car.fwd);
emit(car.pos.x - car.fwd.x * 1.3 + tv1.x * side, car.pos.y - 0.35, car.pos.z - car.fwd.z * 1.3 + tv1.z * side,
(Math.random() - 0.5) * 2, 1.5 + Math.random(), (Math.random() - 0.5) * 2, 0.55, 0.45, 0.4, 0.5, -1);
}
if (car.boostT > 0 && Math.random() < 0.8) {
emit(car.pos.x - car.fwd.x * 2, car.pos.y - car.fwd.y * 2, car.pos.z - car.fwd.z * 2,
-car.fwd.x * 10 + (Math.random() - 0.5) * 2, -car.fwd.y * 10 + Math.random(), -car.fwd.z * 10 + (Math.random() - 0.5) * 2,
0.22, 1, Math.random() < 0.5 ? 0.55 : 0.85, 0.25, 0);
}
}

function tryLand() {
const list = world.cells.get(cellKey(Math.round(car.pos.x / TILE), Math.round(car.pos.z / TILE)));
if (!list) return false;
let best = null, bs = 0, bu = 0, bh = -1e9;
for (let k = 0; k < list.length; k++) {
const pc = list[k];
if (!pc.S) continue;
if (project(pc, car.pos, -1.6, RIDE + 0.05, RIDE) && PR.h > bh) { best = pc; bs = PR.s; bu = PR.u; bh = PR.h; }
}
if (!best) return false;
evalSurf(best, bs, bu, SF);
if (car.vel.dot(SF.n) > 0) return false;
const align = car.up.dot(SF.n);
let vt = car.vel.dot(SF.t), vl = car.vel.dot(SF.l);
const fa = car.fwd.dot(SF.t), fb = car.fwd.dot(SF.l);
const a = fa * fa + fb * fb > 1e-4 ? Math.atan2(fb, fa) : Math.atan2(vl, vt);
const impact = -car.vel.dot(SF.n);
let keep = 0.97;
if (align < 0.35) {
keep = 0.3;
noise(0.3, { filter: 300, vol: 0.32 }); snd(140, 0.25, { type: 'square', slide: 60, vol: 0.08 });
addShake(0.5);
burst(car.pos.x, car.pos.y, car.pos.z, 18, 9, 0.5, 1, 0.6, 0.3, 14, false);
} else if (align < 0.85) keep = 0.6 + 0.37 * (align - 0.35) / 0.5;
vt *= keep; vl *= keep;
car.mode = 'ground'; car.pc = best; car.s = bs; car.u = clamp(bu, -(best.def.pipe ? LIM_PIPE : LIM_FLAT), best.def.pipe ? LIM_PIPE : LIM_FLAT);
car.a = a; car.vt = vt; car.vl = vl; car.airT = 0; car.offT = 0; car.landT = 0.25;
updateGroundPose();
if (impact > 6 && align >= 0.35) {
noise(0.12, { filter: 500, vol: Math.min(0.25, 0.05 + impact * 0.008) });
if (impact > 18) addShake(0.2);
for (let k = 0; k < 12; k++) {
const ang = k / 12 * TAU;
emit(car.pos.x, car.pos.y - 0.4, car.pos.z, Math.cos(ang) * 6, 1.5, Math.sin(ang) * 6, 0.45, 0.8, 0.65, 0.75, 2);
}
}
return true;
}

function airStep(dt) {
car.airT += dt;
car.vel.y -= GRAV * dt;
car.vel.multiplyScalar(1 - 0.03 * dt);
car.pos.addScaledVector(car.vel, dt);
car.speed = car.vel.length();
if (car.steer !== 0) { tq1.setFromAxisAngle(UPV, car.steer * 1.6 * dt); car.q.premultiply(tq1); }
tv1.set(0, 0, 1).applyQuaternion(car.q);
tv1.y = 0;
if (tv1.lengthSq() < 1e-4) { tv1.set(car.vel.x, 0, car.vel.z); if (tv1.lengthSq() < 1e-4) tv1.set(0, 0, 1); }
tv1.normalize();
const hs = Math.sqrt(car.vel.x * car.vel.x + car.vel.z * car.vel.z);
const pitch = clamp(Math.atan2(car.vel.y, Math.max(hs, 1)) * 0.6, -0.9, 0.9);
tv2.copy(tv1).multiplyScalar(Math.cos(pitch)); tv2.y = Math.sin(pitch);
tv3.set(0, 1, 0).addScaledVector(tv2, -tv2.y).normalize();
tv4.crossVectors(tv3, tv2);
tm1.makeBasis(tv4, tv3, tv2);
tq2.setFromRotationMatrix(tm1);
car.q.slerp(tq2, 1 - Math.exp(-2.2 * dt));
car.fwd.set(0, 0, 1).applyQuaternion(car.q);
car.up.set(0, 1, 0).applyQuaternion(car.q);
if (tryLand()) return;
if (!world.cells.has(cellKey(Math.round(car.pos.x / TILE), Math.round(car.pos.z / TILE)))) car.offT += dt;
else car.offT = 0;
if (car.offT > 1 || car.pos.y < -40 || car.airT > 7) autoRespawn();
}

let race = null;
const REC = new Int16Array(GHOST_MAX * 7);
const pbs = CAMPAIGN.map(function (tr) {
try {
const raw = api.load('pb-' + tr.id);
if (!raw) return null;
const o = JSON.parse(raw);
if (!o || typeof o.t !== 'number' || !(o.t > 0)) return null;
return { t: o.t, s: Array.isArray(o.s) ? o.s.filter(function (x) { return typeof x === 'number'; }) : [], g: typeof o.g === 'string' ? o.g : '', gd: null };
} catch (e) { return null; }
});
let bestScore = null;
try { bestScore = api.best(); } catch (e) { bestScore = null; }
function medalPoints() {
let sum = 0;
for (let i = 0; i < CAMPAIGN.length; i++) sum += pbs[i] ? medalFor(i, pbs[i].t) : 0;
return sum;
}
function unlocked(i) { return i === 0 || !!pbs[i - 1]; }
function decodeGhost(str) {
try {
const u8 = b64dec(str);
if (!u8.length || u8.length % 14) return null;
const buf = new ArrayBuffer(u8.length);
new Uint8Array(buf).set(u8);
return { d: new Int16Array(buf), n: u8.length / 14 };
} catch (e) { return null; }
}
function getGhost(i) {
const pb = pbs[i];
if (!pb) return null;
if (!pb.gd && pb.g) pb.gd = decodeGhost(pb.g);
return pb.gd && pb.gd.n > 1 ? pb.gd : null;
}
function savePB(i, ms, splits, recN) {
const data = { t: ms, s: splits.slice(), g: recN > 1 ? b64enc(new Uint8Array(REC.buffer, 0, recN * 14)) : '' };
let ok = false;
try { ok = api.save('pb-' + CAMPAIGN[i].id, JSON.stringify(data)); } catch (e) { ok = false; }
if (!ok && data.g) { try { api.save('pb-' + CAMPAIGN[i].id, JSON.stringify({ t: data.t, s: data.s, g: '' })); } catch (e) { /* storage blocked */ } }
pbs[i] = { t: ms, s: data.s, g: data.g, gd: recN > 1 ? { d: REC.slice(0, recN * 7), n: recN } : null };
}
function recordPose() {
const k = race.recN * 7;
REC[k] = clamp(Math.round(car.pos.x * 20), -32767, 32767);
REC[k + 1] = clamp(Math.round(car.pos.y * 20), -32767, 32767);
REC[k + 2] = clamp(Math.round(car.pos.z * 20), -32767, 32767);
let qx = car.q.x, qy = car.q.y, qz = car.q.z, qw = car.q.w;
if (k >= 7 && REC[k - 4] * qx + REC[k - 3] * qy + REC[k - 2] * qz + REC[k - 1] * qw < 0) { qx = -qx; qy = -qy; qz = -qz; qw = -qw; }
REC[k + 3] = Math.round(qx * 32000); REC[k + 4] = Math.round(qy * 32000); REC[k + 5] = Math.round(qz * 32000); REC[k + 6] = Math.round(qw * 32000);
race.recN++;
}
function ghostPose(t) {
const G = race && race.ghost;
if (!G) return false;
let k = t / GHOST_DT;
if (k > G.n - 1) { if (t > (G.n - 1) * GHOST_DT + 1) return false; k = G.n - 1; }
let i = Math.floor(k);
if (i >= G.n - 1) i = G.n - 2;
const w = clamp(k - i, 0, 1), a = i * 7, b = a + 7, D = G.d;
ghostMesh.position.set(lerp(D[a], D[b], w) / 20, lerp(D[a + 1], D[b + 1], w) / 20, lerp(D[a + 2], D[b + 2], w) / 20);
tq1.set(D[a + 3], D[a + 4], D[a + 5], D[a + 6]).normalize();
tq2.set(D[b + 3], D[b + 4], D[b + 5], D[b + 6]).normalize();
ghostMesh.quaternion.copy(tq1).slerp(tq2, w);
return true;
}
function resetGates() {
if (!world) return;
for (let i = 0; i < world.gates.length; i++) {
const g = world.gates[i];
g.side = (car.pos.x - g.px) * g.tx + (car.pos.y - g.py) * g.ty + (car.pos.z - g.pz) * g.tz;
}
}
function placeAtGate(g, dir, isStart) {
car.mode = 'ground'; car.pc = g.piece;
car.s = clamp(g.s - (isStart ? 4 : 0) * dir, 0.1, g.piece.len - 0.1);
car.u = 0; car.a = dir > 0 ? 0 : Math.PI; car.vt = 0; car.vl = 0; car.steer = 0;
car.boostT = 0; car.boostTo = 0; car.boostPc = null; car.airT = 0; car.offT = 0; car.landT = 0; car.drifting = false;
updateGroundPose();
car.prevPos.copy(car.pos); car.prevQ.copy(car.q);
resetGates();
camSnap = true;
}
function parkCar() { if (world && world.start) placeAtGate(world.start, 1, true); }
function startRace(idx, test) {
closeCodeBox();
ed.modal = null;
if (!test) {
selTrack = idx;
if (!world || world.key !== 'c' + idx) buildWorld(campaignPieces(idx), 'c' + idx, true);
} else if (!world || world.key !== 'ed' || ed.rebuild) { buildWorld(ed.pieces, 'ed', !world || world.key !== 'ed'); ed.rebuild = false; }
if (!world.start) return false;
race = {
test: !!test, idx: idx, phase: 'count', countT: 3, t: 0, goT: 0, cpGot: world.cps.map(function () { return false; }), cpN: 0,
splits: [], lastGate: world.start, lastDir: 1, ghost: test ? null : getGhost(idx), recN: 0, splitT: 0, splitDelta: null,
splitMs: 0, splitIdx: 0, msg: '', msgT: 0, result: null, beep: 4, engineT: 0, respawns: 0,
};
placeAtGate(world.start, 1, true);
acc = 0;
state = 'race'; paused = false;
return true;
}
function restartRace() { if (race) startRace(race.idx, race.test); }
function respawn() {
if (!race || race.phase !== 'run') return;
placeAtGate(race.lastGate, race.lastDir, race.lastGate.kind === 1);
race.respawns++;
snd(520, 0.14, { type: 'sine', slide: 300, vol: 0.12 });
burst(car.pos.x, car.pos.y, car.pos.z, 24, 6, 0.6, 0.45, 0.95, 1, 0, false);
}
function autoRespawn() {
if (race && race.phase === 'run') respawn();
else if (race) { car.mode = 'frozen'; }
}
function checkGates() {
const gs = world.gates;
for (let i = 0; i < gs.length; i++) {
const g = gs[i];
const dx = car.pos.x - g.px, dy = car.pos.y - g.py, dz = car.pos.z - g.pz;
const al = dx * g.tx + dy * g.ty + dz * g.tz, prev = g.side;
g.side = al;
if ((prev < 0) === (al < 0) || Math.abs(prev - al) > 5) continue;
const lat = dx * g.lx + dy * g.ly + dz * g.lz, hn = dx * g.nx + dy * g.ny + dz * g.nz;
if (Math.abs(lat) > HW + 1.2 || hn < -2 || hn > 9) continue;
onGate(g, al > prev ? 1 : -1);
if (race.phase !== 'run') return;
}
}
function onGate(g, dir) {
if (g.kind === 2) {
const ci = world.cps.indexOf(g);
if (ci < 0 || race.cpGot[ci]) return;
race.cpGot[ci] = true; race.cpN++;
const ms = Math.round(race.t * 1000);
race.splits.push(ms);
const pb = !race.test && !race.online && pbs[race.idx];
race.splitIdx = race.cpN; race.splitMs = ms; race.splitT = 2.4;
race.splitDelta = pb && pb.s.length >= race.cpN ? ms - pb.s[race.cpN - 1] : null;
race.lastGate = g; race.lastDir = dir;
snd(660, 0.1, { type: 'triangle', vol: 0.14 }); snd(990, 0.14, { type: 'triangle', vol: 0.12, delay: 0.08 });
burst(g.px + g.nx * 4, g.py + g.ny * 4, g.pz + g.nz * 4, 30, 9, 0.9, 0.35, 0.95, 1, 6, true);
} else if (g.kind === 3) {
if (race.cpN >= world.cps.length) { if (race.online && race.lap < race.laps) netLap(); else finishRace(); }
else if (race.msgT <= 0) { race.msg = 'Missed a checkpoint!'; race.msgT = 1.8; snd(180, 0.2, { type: 'square', vol: 0.08 }); }
}
}
function finishRace() {
if (race.online) { netFinishLocal(); return; }
race.phase = 'done';
const ms = Math.round(race.t * 1000);
const res = { ms: ms, test: race.test, medal: 0, prev: null, newPB: false, points: 0, newBest: false, delta: null };
if (!race.test) {
const i = race.idx, pb = pbs[i];
res.prev = pb ? pb.t : null;
res.delta = pb ? ms - pb.t : null;
if (!pb || ms < pb.t) { res.newPB = true; savePB(i, ms, race.splits, race.recN); }
res.medal = medalFor(i, ms);
res.points = medalPoints();
let nb = false;
try { nb = !!api.submit(res.points); } catch (e) { nb = false; }
res.newBest = nb;
try { bestScore = api.best(); } catch (e) { /* keep the old value */ }
}
race.result = res;
state = 'over'; overAt = performance.now(); paused = false;
const fg = world.finish;
burst(fg.px + fg.nx * 4, fg.py + fg.ny * 4, fg.pz + fg.nz * 4, 70, 12, 1.2, 1, 1, 1, 7, true);
const notes = res.newPB ? [523, 659, 784, 1047] : [523, 659, 784];
for (let k = 0; k < notes.length; k++) snd(notes[k], 0.18, { type: 'triangle', vol: 0.14, delay: k * 0.1 });
}

function readInput(dt) {
const live = state === 'race' && race && race.phase === 'run' && !paused && !omenu;
if (!live) {
inp.gas = false; inp.brake = !!race && race.phase === 'done'; inp.hand = false; inp.steerIn = 0;
} else {
inp.gas = !!(held.KeyW || held.ArrowUp || tc.gas);
inp.brake = !!(held.KeyS || held.ArrowDown || tc.brake);
inp.hand = !!(held.Space || tc.drift);
inp.steerIn = ((held.KeyA || held.ArrowLeft || tc.left) ? 1 : 0) - ((held.KeyD || held.ArrowRight || tc.right) ? 1 : 0);
}
const target = inp.steerIn;
const rate = target === 0 ? 10 : (car.steer * target < 0 ? 14 : 7);
car.steer += clamp(target - car.steer, -rate * dt, rate * dt);
}
function simStep(dt) {
car.prevPos.copy(car.pos); car.prevQ.copy(car.q);
readInput(dt);
if (car.mode === 'ground') groundStep(dt);
else if (car.mode === 'air') airStep(dt);
car.boostT = Math.max(0, car.boostT - dt);
car.wallT -= dt;
if (car.landT > 0) car.landT = Math.max(0, car.landT - dt);
if (car.drifting && car.mode === 'ground') {
car.driftSndT -= dt;
if (car.driftSndT <= 0) { car.driftSndT = 0.16; noise(0.12, { filter: 2600, vol: 0.04 }); }
}
if (race.phase === 'run') {
race.t += dt;
checkGates();
while (!race.online && race.phase === 'run' && race.recN < GHOST_MAX && race.recN * GHOST_DT <= race.t + 1e-9) recordPose();
}
}

let state = 'title';      // title | select | race | over | editor
