cursorBox.scale.set((x1 - x0 + 1) * TILE - 0.6, def.occ * LVL + SLAB, (z1 - z0 + 1) * TILE - 0.6);
cursorMat.color.setHex(ok ? 0xffc93c : 0xff5d5d);
