function coursePar(def) {
let t = 0;
for (let i = 0; i < def.ops.length; i++) {
const o = def.ops[i], k = o[0];
if (k === 'R') {
t += o[1] / 9.0;
const f = o[3] || [];
for (let j = 0; j < f.length; j++) {
const fk = f[j][0];
if (fk === 'low') t += 0.05;
else if (fk === 'block') t += (f[j][3] || 1) > 1.3 ? 0.35 : 0.1;
else if (fk === 'pad') t -= 0.35;
else if (fk === 'fin') t -= Math.max(0, (o[1] - f[j][1]) / 9.0);
}
} else if (k === 'RS') t += o[1] / 12.5;
else if (k === 'RT') t += o[1] / 8.0;
else if (k === 'G') t += o[1] / (o[1] >= 7 ? 12.5 : 9.5) + (o[2] >= 1.25 ? 0.35 : 0);
else if (k === 'GW') t += o[1] / 10;
else if (k === 'GWW') t += o[1] / 9.5;
else if (k === 'GZ') t += (o[1] + 7) / 13;
else if (k === 'GS') t += o[1] / 8.5;
}
return Math.max(10, t - 3 / 9.0); // the run starts 3 m into the first roof
}
function halfUp(t) { return Math.ceil(t * 2) / 2; }
for (let i = 0; i < COURSES.length; i++) {
const p = coursePar(COURSES[i]);
COURSES[i].medals = [halfUp(p * 1.7), halfUp(p * 1.32), halfUp(p * 1.12), halfUp(p * 1.0)];
}
function medalFor(ci, t) {
if (!(t > 0)) return -1;
const m = COURSES[ci].medals;
let best = -1;
for (let k = 0; k < 4; k++) if (t <= m[k] + 1e-6) best = k;
return best;
}

function encodeGhost(buf, n) {
const bytes = new Uint8Array(16 + n * 4 * 5);
let o = 0;
function put(v) {
let u = v >= 0 ? v * 2 : -v * 2 - 1;
while (u >= 128) { bytes[o++] = (u % 128) | 128; u = Math.floor(u / 128); }
bytes[o++] = u;
}
bytes[o++] = 1; // format version
put(n);
let px = 0, py = 0, pz = 0, pa = 0;
for (let i = 0; i < n; i++) {
const qx = Math.round(buf[i * 4] * 20), qy = Math.round(buf[i * 4 + 1] * 20), qz = Math.round(buf[i * 4 + 2] * 20);
const qa = ((Math.round(buf[i * 4 + 3] / TAU * 256) % 256) + 256) % 256;
let da = qa - pa;
if (da > 127) da -= 256; else if (da < -128) da += 256;
put(qx - px); put(qy - py); put(qz - pz); put(i === 0 ? qa : da);
px = qx; py = qy; pz = qz; pa = qa;
}
let s = '';
for (let i = 0; i < o; i += 4096) s += String.fromCharCode.apply(null, bytes.subarray(i, Math.min(o, i + 4096)));
return btoa(s);
}
function decodeGhost(str, out, maxN) {
const bin = atob(str), len = bin.length;
let o = 0;
function get() {
let u = 0, mul = 1, guard = 0;
for (;;) {
if (o >= len) throw new Error('ghost: truncated');
const b = bin.charCodeAt(o++);
u += (b & 127) * mul;
if (b < 128) break;
mul *= 128;
if (++guard > 5) throw new Error('ghost: bad varint');
}
return (u % 2) ? -(u + 1) / 2 : u / 2;
}
if (len < 4 || bin.charCodeAt(o++) !== 1) throw new Error('ghost: bad version');
const n = get();
if (!(n >= 2 && n <= maxN)) throw new Error('ghost: bad length');
let x = 0, y = 0, z = 0, a = 0;
for (let i = 0; i < n; i++) {
x += get(); y += get(); z += get();
const d = get();
a = i === 0 ? d : (((a + d) % 256) + 256) % 256;
out[i * 4] = x / 20; out[i * 4 + 1] = y / 20; out[i * 4 + 2] = z / 20; out[i * 4 + 3] = a / 256 * TAU;
}
return n;
}

