if (!noBottom) sq(b, [x0, y0, z0, x1, y0, z0, x1, y0, z1, x0, y0, z1], hex, flat, null, cx, cy, cz);
const v0 = uv ? y0 / su : 0, v1 = uv ? y1 / su : 0, us = uv ? su : 1;
