TL.rowX = TL.lx + 14; TL.rowW = TL.lw - 28; TL.rowY0 = TL.ly + 108;
TL.rx = Math.max(TL.lx + TL.lw + 16, LW - 24 - 360); TL.rw = Math.max(260, Math.min(360, LW - 24 - TL.rx));
TL.ry = 70; TL.rh = 372;
