function ensureLabels() {
if (medalLblFor === courseIdx) return;
medalLblFor = courseIdx;
for (let k = 0; k < 4; k++) medalLbl[k] = MEDALS[k].name.toUpperCase() + '  ' + fmtShort(COURSES[courseIdx].medals[k]);
}
function drawSpeedLines(sp) {
if (settings.rm || sp < 11) return;
const a = clamp((sp - 11) / 9, 0, 1) * 0.45;
const cx = LW / 2, cy = LH / 2, R = Math.sqrt(cx * cx + cy * cy);
ctx.globalAlpha = a; ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 2;
ctx.beginPath();
for (let i = 0; i < SL_N; i++) {
const t = (SL_O[i] + uiT * (1.2 + sp * 0.08)) % 1;
const r0 = R * (0.55 + t * 0.5), r1 = r0 + 30 + sp * 3;
const ca = Math.cos(SL_A[i]), sa = Math.sin(SL_A[i]);
ctx.moveTo(cx + ca * r0, cy + sa * r0); ctx.lineTo(cx + ca * r1, cy + sa * r1);
}
ctx.stroke();
ctx.globalAlpha = 1;
}
function roundBtn(x, y, r, label, on, col) {
ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
ctx.fillStyle = on ? col : 'rgba(16,22,38,0.55)'; ctx.fill();
ctx.strokeStyle = col; ctx.stroke();
txt(ctx, label, x, y + 1, Math.round(r * 0.36), FONT_B, on ? '#10141f' : UI.head, 'center', 0, '800');
}
