deadN:mk(function(g){mDeadTree(g,r);}),deadF:mk(function(g){g.at(0,0,0);g.cyl(0.2,0.05,0,6,4,C3.dead);g.seg([0,3,0],[1.2,4.2,0],0.07,3,C3.dead);g.seg([0,3.6,0],[-1,4.8,0.3],0.06,3,C3.rime);}),
rock:mk(function(g){mRock(g,r,C3.rock);}),chair:mk(mChair),spec:mk(mSpectator),specL:mk(mSpecLight),lantern:mk(mLantern),wand:mk(mWand),chev:mk(mChevron),pole:mk(mRidgePole),flare:mk(mFlare),
beacon:mk(function(g){g.at(0,0,0);g.sph(0,0,0,0.16,6,4,[1,1,1]);})
