const MINOR=[0,2,3,5,7,8,10],BPM=[84,104,104,128,84];
function inMinor(n){return MINOR.indexOf(((n%12)+12)%12)>=0;}
function chordTones(root,deg,out){const r=root+deg;out[0]=r;out[1]=r+(inMinor(deg+3)?3:4);out[2]=r+(inMinor(deg+7)?7:6);out[3]=r+12;return out;}
const CHD=[0,0,0,0];
function mtof(m){return 440*Math.pow(2,(m-69)/12);}
