const MAJ4=[0,4,7,12],DESC8=[0,3,7,12,15,19,24,27];
function stingerStep(t,st,root){
const step=60/AU.bpm/4,win=AU.st==='v';
if(win){const maj=root+3,ch=AU.stT===0?(st<8?5:7):0;if(st%2===0)note(mtof(maj+ch+MAJ4[(st/2)%4]+12),t,step*2,'triangle',0.08);if(st===0)for(let k=0;k<3;k++)pad(mtof(maj+ch+MAJ4[k]),t,step*16,0.04);if(st%4===0)drum(0,t,0.8);}
else{if(st%2===0)note(mtof(root+12-DESC8[(AU.stT*8+st/2)%8]),t,step*2.5,'triangle',0.07);if(st===0)pad(mtof(root-12),t,step*16,0.035);}
}
function auPause(p){if(p&&!AU.paused){snd("whoomp",0.5);AU.dropT=0.6;}AU.paused=p;auLevels();if(p)auStopLoops(true);else if(!AU.ctx)audioPoll(0,true);}
