const UIK={KeyW:'u',ArrowUp:'u',KeyS:'d',ArrowDown:'d',KeyA:'L',ArrowLeft:'L',KeyD:'R',ArrowRight:'R',Enter:'ok',NumpadEnter:'ok',Space:'ok',Escape:'esc',Backspace:'bk',KeyP:'p',KeyQ:'q',KeyE:'e',KeyR:'x',KeyJ:'x',KeyX:'x',KeyK:'x',ShiftLeft:'x',ShiftRight:'x'};
