IN.sp=HELD.sp>0||LT.sp>0;IN.spP=LT.sp>0;IN.spR=LU.sp>0;
IN.gr=HELD.gr>0||LT.gr>0;IN.grP=LT.gr>0;
IN.bo=HELD.bo>0||LT.bo>0;IN.boP=LT.bo>0;
