const HS={st:'',stCol:'',stT:9,ls:'',lsCol:'',lsSub:'',lsT:9,trk:'',trkP:0,trkN:'',trkT:9,bank:0,bankM:0,bankT:9,split:0,splitD:0,splitHas:false,splitT:9,jc:0,jcN:1,jcT:9,hint:-1,hintS:'',hintT:9,tut:-1,tutN:'',tutNT:9,tutR:'',tutRT:9,flash:0,gv:0,cd:4};
const POPS=[],FEED=[],TOQ=[];let popI=0,feedI=0,toI=0,toN=0;
