function perfectFx(r){snd('perfect',0.6);popPts('Perfect Pop',0);fx('perf',r.pos.x,r.pos.y,r.pos.z,16,0,0);}
function boostFx(r,on){if(on){snd('boost',0.6);CAM.kick=6;fx('boost',r.pos.x,r.pos.y,r.pos.z,12,-r.vel.x*0.2,-r.vel.z*0.2);}}
