function splitShow(i,t,d){HS.split=t;HS.splitD=d===null?0:d;HS.splitHas=d!==null;HS.splitT=0;}
function toast(a,b,col,ic){if(toN>=4)return;const q=TOQ[(toI+toN)%4];q.a=a;q.b=b;q.col=col;q.ic=ic;q.t=0;toN++;}
