const CONF = [], CONF_COLS = ['#FFC93C', '#FF5D5D', '#5CE1FF', '#4BE3A0', '#8C7CFF', '#FFFFFF'];
for (let i = 0; i < 120; i++) CONF.push({ x: 0, y: 0, vx: 0, vy: 0, r: 0, vr: 0, c: '#fff', life: 0 });
let confN = 0;
function confetti(n) {
if (reduceMotion) n = Math.min(n, 20);
for (let k = 0; k < n; k++) {
const p = CONF[confN]; confN = (confN + 1) % CONF.length;
p.x = LW / 2 + (Math.random() - 0.5) * 360; p.y = LH * 0.3; p.vx = (Math.random() - 0.5) * 480; p.vy = -180 - Math.random() * 340;
p.r = Math.random() * 6; p.vr = (Math.random() - 0.5) * 12; p.c = CONF_COLS[k % CONF_COLS.length]; p.life = 2 + Math.random();
}
}
function clearConfetti() { for (let i = 0; i < CONF.length; i++) CONF[i].life = 0; }
function updateConfetti(dt) {
for (let i = 0; i < CONF.length; i++) {
const p = CONF[i];
if (p.life <= 0) continue;
p.life -= dt; p.vy += 520 * dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vx *= 1 - dt * 0.8; p.r += p.vr * dt;
}
}
function drawConfetti() {
for (let i = 0; i < CONF.length; i++) {
const p = CONF[i];
if (p.life <= 0) continue;
ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.r); ctx.globalAlpha = Math.min(1, p.life);
ctx.fillStyle = p.c; ctx.fillRect(-4, -2.5, 8, 5); ctx.restore();
}
}
