const o = boltSeg * 18;
boltPos[o] = ax - px; boltPos[o + 1] = ay - py; boltPos[o + 2] = az - pz;
boltPos[o + 3] = ax + px; boltPos[o + 4] = ay + py; boltPos[o + 5] = az + pz;
boltPos[o + 6] = bx + px; boltPos[o + 7] = by + py; boltPos[o + 8] = bz + pz;
boltPos[o + 9] = ax - px; boltPos[o + 10] = ay - py; boltPos[o + 11] = az - pz;
boltPos[o + 12] = bx + px; boltPos[o + 13] = by + py; boltPos[o + 14] = bz + pz;
boltPos[o + 15] = bx - px; boltPos[o + 16] = by - py; boltPos[o + 17] = bz - pz;
