for (let i = 0; i < 8; i++) emit(PN, T.x + (Math.random() - 0.5) * 3, T.y + 0.2, T.z + (Math.random() - 0.5) * 5, (Math.random() - 0.5) * 3, 1.5, (Math.random() - 0.5) * 3, 1, 0.8, 2.2, 0.45, 0.38, 0.3, 0.5, 1.5, 0.2, 0);
