for (let s = 0; s < stops.length; s++) if (v >= stops[s][0]) c = stops[s][1];
RLUT[i * 4] = c < 0 ? 0 : (c >> 16) & 255; RLUT[i * 4 + 1] = c < 0 ? 0 : (c >> 8) & 255;
RLUT[i * 4 + 2] = c < 0 ? 0 : c & 255; RLUT[i * 4 + 3] = c < 0 ? 0 : 215;
