function unlockedList(arr) { let n = 0; for (let i = 0; i < arr.length; i++) if (arr[i]) n++; return n; }
function cycleFrame(d) {
let f = save.frame;
for (let k = 0; k < FRAMES.length; k++) { f = (f + d + FRAMES.length) % FRAMES.length; if (save.frames[f]) break; }
if (f !== save.frame) { save.frame = f; buildPlayerModel(f); persist(); sndUI(700); }
else if (unlockedList(save.frames) < 2) hint('Unlock more frames in the Hangar', 2, 1);
}
