let raf = 0, lastT = performance.now(), dirty = true;
function frame(now) {
if (destroyed) return;
raf = requestAnimationFrame(frame);
let raw = (now - lastT) / 1000;
lastT = now;
if (!(raw > 0)) raw = 0;
const dt = Math.min(raw, 1 / 30);
realT += dt;
if (!paused) {
let sdt = dt;
if (slowT > 0) { slowT -= dt; sdt = dt * 0.35; }
if (NET) netFrame(dt); // may leave the room
if (mode === 'playing' && (!overlay || NET)) {
acc += sdt;
let steps = 0;
while (acc >= SIM && steps < MAX_STEPS && mode === 'playing' && (!overlay || NET)) { step(SIM); acc -= SIM; steps++; }
if (steps >= MAX_STEPS) acc = 0;
updateFX(sdt);
if (mode === 'playing') updateAmbience(dt);
if (NET && overlay) { ovT += dt; lvT += dt; }
} else if (mode === 'playing') { ovT += dt; lvT += dt; }
else if (mode === 'dying' && NET) { dyingT += dt; updateFX(sdt); if (dyingT > 2.5) netResults(); }
else if (mode === 'dying') {
acc += sdt;
let steps = 0;
while (acc >= SIM && steps < MAX_STEPS && mode === 'dying') { stepDyingSim(SIM); acc -= SIM; steps++; }
if (steps >= MAX_STEPS) acc = 0;
updateFX(sdt);
} else if (mode === 'over') { overT += dt; updateFX(dt); }
else { stepTitle(dt); updateFX(dt); P.yaw += dt * 0.45; }
if (hintT > 0 && (!overlay || NET)) hintT -= dt;
if (bannerT > 0 && (!overlay || NET)) bannerT -= dt;
if (hMsgT > 0) hMsgT -= dt;
if (flashA > 0) flashA = Math.max(0, flashA - dt * 2.2);
if (shakeAmt > 0) shakeAmt = Math.max(0, shakeAmt - dt * 1.9);
}
if (!paused || dirty) { syncScene(paused ? 0 : dt); render(); dirty = false; }
drawHUD();
adaptResolution(raw);
}

