ctx.fillStyle = 'rgba(0, 0, 0, 0.55)'; ctx.fillRect(x - 1, y - 1, w + 2, h + 2);
ctx.fillStyle = ally ? UI.ally : UI.danger; ctx.fillRect(x, y, w * clamp(t.hp / t.hpMax, 0, 1), h);
