ctx.fillStyle = UI.hi; ctx.beginPath(); ctx.moveTo(p.x, my - 6 * s); ctx.lineTo(p.x + 5 * s, my); ctx.lineTo(p.x, my + 6 * s); ctx.lineTo(p.x - 5 * s, my); ctx.closePath(); ctx.fill();
