function drawBoard(x, y, w) { // every tank: team, then kills, then fewest deaths
const team = rcfg && rcfg.mode === 'team', K = net.kills, D = net.deaths;
let n = 0;
for (let i = 0; i < MAX_TANKS; i++) if (tanks[i].active) order[n++] = i;
for (let i = 1; i < n; i++) {
const v = order[i], tv = tanks[v], av = team && tv.team !== player.team ? 1 : 0;
let j = i - 1;
while (j >= 0) {
const tj = tanks[order[j]], aj = team && tj.team !== player.team ? 1 : 0;
if (!(aj > av || (aj === av && (K[tj.gid] < K[tv.gid] || (K[tj.gid] === K[tv.gid] && D[tj.gid] > D[tv.gid]))))) break;
order[j + 1] = order[j]; j--;
}
order[j + 1] = v;
}
if (team) { txt(ctx, net.topS, x + w / 2, y, 15, FONT_B, '#FFFFFF', 'center', w, '800'); y += 26; }
txt(ctx, 'TANK', x + 16, y, 11, FONT_B, UI.dim, 'left', 0, '800');
txt(ctx, 'KILLS', x + w - 90, y, 11, FONT_B, UI.dim, 'right', 0, '800');
txt(ctx, 'DEATHS', x + w - 12, y, 11, FONT_B, UI.dim, 'right', 0, '800');
for (let r = 0; r < n; r++) {
const t = tanks[order[r]], ry = y + 24 + r * 24;
if (t === player) { ctx.fillStyle = 'rgba(255, 201, 60, 0.1)'; ctx.fillRect(x, ry - 11, w, 22); }
ctx.fillStyle = teamCss(t); ctx.fillRect(x + 4, ry - 5, 4, 10);
txt(ctx, t.name, x + 16, ry, 14, FONT_B, '#FFFFFF', 'left', w - 200, '700');
if (!t.human) txt(ctx, 'BOT', x + w - 150, ry, 10, FONT_B, UI.dim, 'right', 0, '800');
txt(ctx, String(K[t.gid]), x + w - 90, ry, 14, FONT_M, '#FFFFFF', 'right', 0, '700');
txt(ctx, String(D[t.gid]), x + w - 12, ry, 14, FONT_M, UI.body, 'right', 0, '700');
}
}
