let nGrp = 1, x = -380, y = 0, mat = wd.mat, conv = 0, finishX = 0, maxSurf = 0, pit = false;
function pt(nx, ny) { gm.push(mat); gc.push(conv); gp.push(nx, ny); x = nx; y = ny; if (!pit && ny > maxSurf) maxSurf = ny; }
