ctx.fillStyle = '#b07a44'; ctx.fillRect(-w / 2 + 1, -5, w - 2, 2.5);
ctx.fillStyle = '#3a2412'; ctx.fillRect(-w / 2 + 4, -1, 2, 2); ctx.fillRect(w / 2 - 6, -1, 2, 2);
