ctx.fillStyle = 'rgba(255,255,255,0.12)'; ctx.beginPath(); rrect(ctx, x0, by, bw, 8, 4); ctx.fill();
const prog = clamp((rbx - T.spawns[0].x) / span, 0, 1);
