drawMedal(ctx, x + 9, 30, 9, hidden ? 0 : lvl);
if (hidden) { ctx.font = F_S14; ctx.fillStyle = COL.dim; ctx.textAlign = 'center'; ctx.fillText('?', x + 9, 35); }
