const NPL = 8, NBUF = 8, PEN = 5000, NET_DT = 0.05, QUIET = 8;   // pose: [hostTime, x, y, angle, lean, phase, faults, respawns]
const GH_COL = ['#9fe6ff', '#ffb35c', '#c6ff3d', '#ff8ad8'], ORDS = ['', '1st', '2nd', '3rd', '4th'], ORD = [0, 0, 0, 0];
const ON_GO = [300, 304, 360, 50], ON_BACK = [20, 22, 100, 34], ON_LBL = ['RACES', 'WINS', 'PODIUMS'];
const LB_Y = [96, 164, 232], LB_X = 60, LB_W = 460, LB_H = 58, LB_START = [60, 314, 220, 46], LB_LEAVE = [300, 314, 220, 46], LB_LBL = ['TRACK', 'TRACK POOL', 'BIKES'];
const OM_BOX = [320, 196, 320, 214], OM_RES = [350, 262, 260, 44], OM_LEAVE = [350, 316, 260, 44];
const NR_BTNS = [[246, 446, 150, 42, 'REMATCH'], [405, 446, 150, 42, 'NEXT TRACK'], [564, 446, 150, 42, 'LEAVE']];
const NR_ACT = ['Press Space for a rematch', 'Press Space for the next track', 'Press Space to leave the room'];
const RPZ = newPose(); RPZ.ghost = true;
let N = null, nOpen = false, nTok = 0, netMsg = '', omenu = false;
const orec = { r: 0, w: 0, p: 0 };   // local online record: races, wins, podiums
try {
const o = JSON.parse((typeof api.load === 'function' && api.load('online')) || 'null');
if (o && typeof o === 'object') for (const k in orec) { const v = Number(o[k]); if (isFinite(v) && v >= 0 && v < 1e7) orec[k] = v | 0; }
} catch (e) { /* no record yet */ }
const nm = (v, lo, hi, d) => { v = Number(v); return isFinite(v) && v >= lo && v <= hi ? v : d; };
const r10 = (v) => Math.round(v * 10) / 10;
function hostT() { if (N) { try { const t = N.s.hostTime(); if (isFinite(t)) return t; } catch (e) { /* local clock */ } } return performance.now(); }
function nSend(m, o) { if (N) try { N.s.send(m, o); } catch (e) { /* closing */ } }
function nCast(m, o) { if (N) try { N.s.broadcast(m, o); } catch (e) { /* closing */ } }
function myBike() { return bikeOpen(save.bike) ? save.bike : 0; }
function myMask() { let m = 1; for (let i = 0; i < NT; i++) if (trackOpen(i)) m |= 1 << i; return m; }
const TRK_N = TRACKS.map(function (t, i) { return (Math.floor(i / 6) + 1) + '-' + (i % 6 + 1) + '  ' + t.n; });   // lobby labels, built once
const RID_N = [0, 1, 2, 3, 4].map(function (n) { return n + ' of 4 riders  \u00B7  ghost bikes, no collisions'; });
function mkRider(i) {
return { name: 'Player ' + (i + 1), lab: '', col: GH_COL[i], on: false, known: false, mask: 1, bike: 0, inR: false, left: false, fin: -1, f: 0, x: 0, prog: 0,
seen: 0, tagW: 60, tStr: '', px: 0, ok: false, vis: false, nn: 0, age: 0, nt: new Float64Array(NBUF), nd: new Float64Array(NBUF * NPL) };
}
function poolHas(i) {
if (N.any) return true;
for (let p = 0; p < 4; p++) { const r = N.rid[p]; if (r.on && r.known && !(r.mask & (1 << i))) return false; }
return true;
}
function poolStep(t, d) { for (let k = 0; k < NT; k++) { t = (t + d + NT) % NT; if (poolHas(t)) return t; } return 0; }
function poolFix() { if (!poolHas(N.ti)) N.ti = poolStep(N.ti, -1); }

function openOnline() {
state = 'online'; paused = false; omenu = false; netMsg = '';
clearInput(); engineStop();
}
function netOpen() {
if (nOpen || N || !NET || !NET.supported) return;
nOpen = true; netMsg = '';
const tk = ++nTok;
let p = null;
try { p = NET.open({ maxPlayers: 4, modeLabel: 'Ghost Race' }); } catch (e) { p = null; }
if (p && typeof p.then === 'function') p.then(function (s) { netOpened(s, tk); }, function () { netOpened(null, tk); });
else netOpened(p, tk);
}
function netOpened(s, tk) {
if (tk !== nTok) { if (s) try { s.close(); } catch (e) { /* ignore */ } return; }
nOpen = false;
if (!s) return;
if (destroyed || N || state !== 'online') { try { s.close(); } catch (e) { /* ignore */ } return; }
try { netStart(s); } catch (e) { if (!N) try { s.close(); } catch (e2) { /* ignore */ } netQuit(false); netExit('Online play hit a problem. Try again.'); }
}
function netStart(s) {
const host = s.role === 'host';
N = { s: s, host: host, me: host ? 0 : nm(s.me, 1, 3, 1) | 0, rid: [], ti: trackOpen(selIdx) ? selIdx : 0, any: false, same: false, lob: host,
rn: 0, race: false, cd: false, cdS: 0, go: 0, goFx: 0, dl: 0, dlK: -9, dlStr: '', finLine: '', endAt: 0, res: null, lastGo: null, lastRes: null,
lastH: -1, sendT: 0, hbT: 0, quiet: 0, needAt: 0, fsDirty: false, sp: 0, lastSince: 0, foc: host ? 3 : -1, mf: 0 };
for (let i = 0; i < 4; i++) N.rid.push(mkRider(i));
const P = Array.isArray(s.players) ? s.players : [];
for (let i = 0; i < P.length; i++) {
const p = P[i] || {}, ix = nm(p.index, 0, 3, -1) | 0;
if (ix >= 0) { N.rid[ix].name = String(p.name || 'Player ' + (ix + 1)).slice(0, 12); N.rid[ix].on = p.connected !== false; }
}
const me = N.rid[N.me];
me.on = true; me.known = true; me.mask = myMask(); me.bike = myBike();
for (let i = 0; i < 4; i++) { const r = N.rid[i]; r.lab = i === N.me ? r.name + ' (you)' : i === 0 ? r.name + ' (host)' : r.name; }
s.on('message', onNetMsg); s.on('leave', onNetLeave); s.on('close', onNetClose);
state = 'lobby'; clearInput();
if (host) { poolFix(); lobSend(); } else nSend({ t: 'hi', u: me.mask, b: me.bike });
}
function lobSend() {
if (!N || !N.host) return;
const r = [];
for (let i = 0; i < 4; i++) { const o = N.rid[i]; if (o.on) r.push([i, o.bike, o.known ? 1 : 0]); }
nCast({ t: 'lob', ti: N.ti, any: N.any ? 1 : 0, same: N.same ? 1 : 0, r: r });
N.hbT = 0;
}

function onNetMsg(m, from) {
if (!N || !m || typeof m !== 'object') return;
from = from | 0;
if (!N.host) N.quiet = 0;
else if (from > 0 && from < 4) N.rid[from].seen = hostT();
try { netRecv(m, from); } catch (e) { /* a malformed message is ignored */ }
}
function netRecv(m, from) {
const t = m.t;
if (N.host) {
if (from < 1 || from > 3) return;
const r = N.rid[from];
if (t === 'hi') {
r.mask = (nm(m.u, -2147483648, 2147483647, 1) | 0) | 1; r.bike = nm(m.b, 0, BIKES.length - 1, 0) | 0; r.known = true;
if (state === 'lobby') { poolFix(); lobSend(); }
} else if (t === 'need') { if (N.race && N.lastGo) try { N.s.send(N.lastGo, { to: from }); } catch (e) { /* closing */ } }
else if (!N.race || m.rn !== N.rn || !r.inR) return;
else if (t === 'p') { if (Array.isArray(m.d)) netPush(r, m.d, 0); }
else if (t === 'fin') hostFin(r, m.ms, Math.max(nm(m.f, 0, 999, 0), r.f));   // never fewer faults than its poses showed
return;
}
if (t === 'lob') netLob(m);
else if (t === 'go') netBegin(m);
else if (t === 'res') { if (m.rn === N.rn) netResults(m.r); }
else if (t === 's' && m.rn > N.rn) {   // a race is on that I never heard start: ask for it again
const now = performance.now();
if (now > N.needAt) { N.needAt = now + 2000; nSend({ t: 'need' }); }
} else if (!N.race || m.rn !== N.rn) return;
else if (t === 's') netSnap(m);
else if (t === 'fs') netFs(m);
}
