if (p.ok) pill(p.x, p.y - 12 * s, (FOC.kind === 'needcard' ? '' : (touchUI ? 'USE: ' : 'E: ')) + FOC.label, Math.round(13 * s), FOC.kind === 'needcard' ? UI.danger : UI.hi);
