c.beginPath(); c.arc(cx, cy, R, 0, TAU); c.stroke();
c.beginPath(); c.arc(cx, cy, R * 0.5, 0, TAU); c.stroke();
c.beginPath(); c.moveTo(cx - R, cy); c.lineTo(cx + R, cy); c.moveTo(cx, cy - R); c.lineTo(cx, cy + R); c.stroke();
const range = run.jam ? 170 : 650;
