if (me) { ctx.fillStyle = 'rgba(255, 201, 60, 0.1)'; ctx.fillRect(x + 4, y, w - 8, ROW_H - 4); }
if (P.fl > 0) { ctx.globalAlpha = P.fl * 0.45; ctx.fillStyle = KINDS.storm.glow; ctx.fillRect(x + 4, y, w - 8, ROW_H - 4); ctx.globalAlpha = 1; }
ctx.textAlign = 'left';
